import { useRef, useState, type CSSProperties } from "react";
import { BackgroundOrchestrator } from "./BackgroundOrchestrator";
import { CornerOrnament } from "./covers/CornerOrnament";
import { useFitText } from "./hooks/useFitText";
import { PhotoLightbox } from "./PhotoLightbox";
import { pageStyleClass, resolvePageStyle } from "./utils/pageStyle";
import { arrangePhotos, hasMedia, readPageMedia } from "./utils/media";
import type { AlbumConfig, GreetingPart, PageConfig } from "./types";

export interface GreetingPageProps {
  album: AlbumConfig;
  page: PageConfig;
  /**
   * Renders one half of a greeting that was split across two pages. Omit it to
   * render whatever the greeting has, which is what single-page greetings want.
   */
  part?: GreetingPart;
  /**
   * Shrink an over-long greeting to fit. Set false in layouts whose pages grow
   * with their content, where there is nothing to fit into. Defaults to true.
   */
  fitToPage?: boolean;
}

/**
 * Renders a single greeting: optional media (a video player or a photo
 * collage) plus the styled Hebrew wish. Typography resolves page override →
 * album default → engine fallback, so an album-wide choice reaches every
 * greeting that has not asked for its own.
 */
export function GreetingPage({
  album,
  page,
  part,
  fitToPage = true,
}: GreetingPageProps) {
  const bodyRef = useRef<HTMLDivElement>(null);
  const [zoomed, setZoomed] = useState<string | null>(null);

  const fontSize = page.fontSize || album.defaultFontSize || "18px";
  const textStyle: CSSProperties = {
    fontFamily: page.fontFamily || album.defaultFontFamily || "Rubik",
    // The chosen size stays here, unscaled, because the body's `max-width` is
    // measured in `ch`: scaling it would narrow the column and win back in
    // extra lines whatever shrinking saved in height. The children apply
    // `--ae-fit` instead, so only the type gets smaller.
    fontSize,
    textAlign: (page.textAlign ||
      album.defaultTextAlign ||
      "right") as CSSProperties["textAlign"],
  };

  // With no colour anywhere the page style supplies the ink, which is how a
  // greeting on a dark page comes out light without anyone choosing gold.
  const ink = page.textColor || album.defaultTextColor;
  if (ink) textStyle.color = ink;

  const media = readPageMedia(page);
  // The signature belongs with the words, so a media-only half carries neither.
  const showText = part !== "photo";
  const showMedia = part !== "text" && hasMedia(media);

  useFitText(bodyRef, fitToPage && showText, [
    page.html,
    page.authorName,
    fontSize,
    textStyle.fontFamily,
    media.photos.join("|"),
    media.videoUrl,
  ]);

  return (
    <BackgroundOrchestrator
      global={album.globalBackground}
      override={page.backgroundConfig}
      ornament={
        <div className="ae-page__ornament" aria-hidden="true">
          <CornerOrnament style={resolvePageStyle(album, page)} surface="page" />
        </div>
      }
      className={[
        "ae-page",
        pageStyleClass(album, Boolean(page.backgroundConfig?.trim()), page),
        part ? `ae-page--${part}` : null,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      {showMedia ? (
        media.videoUrl ? (
          <figure className="ae-page__media">
            {/* preload stays at metadata so an album of video greetings does
                not open thirty streams — only the page actually being watched
                downloads its frames. */}
            <video
              src={media.videoUrl}
              controls
              preload="metadata"
              playsInline
            />
          </figure>
        ) : (
          <PhotoCollage
            photos={media.photos}
            layout={page.photoLayout}
            onZoom={setZoomed}
          />
        )
      ) : null}
      {zoomed ? (
        <PhotoLightbox src={zoomed} onClose={() => setZoomed(null)} />
      ) : null}
      {showText ? (
        // Typography sits on the body so the signature stays proportional to
        // the greeting and both shrink together when the page runs short.
        <div className="ae-page__body" ref={bodyRef} style={textStyle}>
          <div
            className="ae-page__text"
            dangerouslySetInnerHTML={{ __html: page.html }}
          />
          {page.authorName?.trim() ? (
            <p className="ae-page__author">{page.authorName}</p>
          ) : null}
        </div>
      ) : null}
    </BackgroundOrchestrator>
  );
}

/**
 * An auto-collage of one to six photos. Every photo keeps the single-photo
 * treatment — zoom button included, so the lightbox still gives it the whole
 * screen; the collage only changes how they share the page.
 */
function PhotoCollage({
  photos,
  layout,
  onZoom,
}: {
  photos: string[];
  layout?: PageConfig["photoLayout"];
  onZoom: (src: string) => void;
}) {
  const arranged = arrangePhotos(layout, photos);
  if (arranged.photos.length === 0) return null;

  const columns = arranged.columns;
  const lastSpans =
    arranged.mode === "collage" &&
    columns > 1 &&
    arranged.photos.length % columns === 1;

  return (
    <figure
      className={`ae-page__media ae-page__collage ae-page__collage--${arranged.mode}`}
      style={{ "--ae-collage-columns": columns } as CSSProperties}
    >
      {arranged.photos.map((url, index) => (
        <button
            key={`${url}-${index}`}
          type="button"
          className={[
            "ae-page__zoom",
            lastSpans && index === arranged.photos.length - 1 ? "is-spanning" : null,
          ]
            .filter(Boolean)
            .join(" ")}
          aria-label="הגדלת התמונה"
          onClick={() => onZoom(url)}
        >
          <img src={url} alt="" loading="lazy" />
        </button>
      ))}
    </figure>
  );
}
